// Solve solves an alphametics puzzle of the form "A + B == C".
// It returns a map of each letter to its digit, or an error if no
// solution exists.
func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, fmt.Errorf("invalid puzzle: %q", puzzle)
	}
	addends := strings.Split(eq[0], "+")
	words := append(addends, strings.TrimSpace(eq[1]))

	// Compute the coefficient of each letter from its place values.
	coeff := make(map[rune]int)
	leading := make(map[rune]bool)
	for _, w := range words {
		w = strings.TrimSpace(w)
		if len(w) > 1 {
			leading[rune(w[0])] = true
		}
		power := 1
		for i := len(w) - 1; i >= 0; i-- {
			coeff[rune(w[i])] += power
			power *= 10
		}
	}

	if len(coeff) > 10 {
		return nil, errors.New("no solution: more than ten distinct letters")
	}

	// Order letters by decreasing absolute coefficient for better pruning.
	letters := make([]rune, 0, len(coeff))
	for l := range coeff {
		letters = append(letters, l)
	}
	sort.Slice(letters, func(i, j int) bool {
		return abs(coeff[letters[i]]) > abs(coeff[letters[j]])
	})

	assign := make(map[rune]int)
	used := make([]bool, 10)
	var solve func(i int, sum int) bool
	solve = func(i int, sum int) bool {
		if i == len(letters) {
			return sum == 0
		}
		l := letters[i]
		bound := 0
		for j := i + 1; j < len(letters); j++ {
			bound += 9 * abs(coeff[letters[j]])
		}
		if abs(sum) > bound {
			return false
		}
		for d := 0; d < 10; d++ {
			if used[d] {
				continue
			}
			if d == 0 && leading[l] {
				continue
			}
			used[d] = true
			assign[l] = d
			if solve(i+1, sum+coeff[l]*d) {
				return true
			}
			used[d] = false
		}
		delete(assign, l)
		return false
	}

	if !solve(0, 0) {
		return nil, errors.New("no solution")
	}

	result := make(map[string]int, len(assign))
	for l, d := range assign {
		result[string(l)] = d
	}
	return result, nil
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
